class TerrainLakeTest{public static void main(String[]a){int n=256;var b=new EnvironmentMap(new float[n*n]);b.height=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)b.height[z*n+x]=(float)(90+180*Math.max(0,(x-128)/100.));var node=new TerrainGraph.Node(7,TerrainGraph.Type.LAKE,0,0);node.values.put("random",0.0);node.values.put("x",50.0);node.values.put("z",50.0);node.values.put("radius",25.0);node.values.put("level",82.0);node.values.put("overflow",0.0);node.values.put("terrainFit",0.0);var standard=EnvironmentNodes.apply(node,b,null,n,4096,62,71,()->false);node.values.put("terrainFit",1.0);var fitted=EnvironmentNodes.apply(node,b,null,n,4096,62,71,()->false);int oldUphill=0,newUphill=0,low=0;for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*n+x;if(x>140){if(standard.lakeMask[i]!=0)oldUphill++;if(fitted.lakeMask[i]!=0)newUphill++;}if(x<120&&fitted.lakeMask[i]!=0)low++;}if(newUphill>=oldUphill||low<100)throw new AssertionError("Shoreline does not adapt to hills");System.out.println("PASS: uphill lake cells reduced "+oldUphill+" -> "+newUphill+" with lowland bays preserved="+low);}}
